"""Replays the demo scenarios against the real app (offline, no LLM) and writes docs/DEMO_OUTPUT.md.

    python scripts/run_demo.py
"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "app"))

from fastapi.testclient import TestClient  # noqa: E402

from clinical_draft import create_clinical_draft  # noqa: E402
from main import app  # noqa: E402

client = TestClient(app)
out = ["# Demo: documented API calls with real outputs",
       "",
       "Generated by `python scripts/run_demo.py` (offline, rules-only mode, synthetic data). "
       "Repetitive fields (`interpretation`, `sources`, `available_reports`, `session_id`) are omitted for readability; the intent and latency are in each header line.", ""]
n = 0


def trim(obj):
    drop = {"interpretation", "available_reports", "sources", "session_id"}
    if isinstance(obj, dict):
        return {k: trim(v) for k, v in obj.items() if k not in drop}
    if isinstance(obj, list):
        return [trim(x) for x in obj]
    return obj


def step(title, method, path, body=None, note=None, files=None):
    global n
    n += 1
    r = client.request(method, path, json=body) if files is None else client.post(path, files=files)
    data = r.json()
    interp = data.get("interpretation") or {}
    out.append(f"## {n}. {title}")
    if note:
        out.append(f"_{note}_")
    out.extend(["", "```http", f"{method} {path}", "```"])
    if body is not None:
        out.extend(["```json", json.dumps({k: v for k, v in body.items() if k != "session_id"}, indent=2), "```"])
    meta = f"HTTP {r.status_code}"
    if interp:
        meta += f" | intent={interp['intent']} (via {interp['source']}) | latency={data.get('latency_ms')} ms"
    out.extend([f"**Response** ({meta})", "```json", json.dumps(trim(data), indent=2, ensure_ascii=False), "```", ""])
    return data


ask = lambda title, text, **kw: step(title, "POST", "/assistant/message", {"text": text, **kw})

step("Health check", "GET", "/")
a = ask("Feature A: ambiguous name, system asks instead of guessing", "Open Priya's latest OPG report")
sid = a["session_id"]
ask("Feature A: clinician picks a candidate (by patient ID); original OPG request is remembered", "select", session_id=sid, patient_id="P002")
ask("Feature C: 'her' resolved from session, evidence shown", "Summarize her report", session_id=sid)
ask("Bonus chatbot: grounded answer with the exact sentence", "Is there any periapical lesion?", session_id=sid)
ask("Bonus chatbot: topic not in report, so no guessing", "Is there a fracture?", session_id=sid)
ask("Bonus chatbot: tooth-specific question does not borrow another tooth's finding", "Is there caries on tooth 36?", session_id=sid)
ask("Bonus chatbot: clinical judgment refused", "Will the patient need surgery?", session_id=sid)
ask("Feature C safety: pronoun contradicts patient gender, so it asks", "Summarize his report", session_id=sid)
ask("Feature A: direct unique match (single patient)", "Show me Aman Saxena's latest OPG")
ask("Feature A: patient exists but has no OPG", "Open Neha Kapoor's OPG")
ask("Feature A: unsupported report type is rejected, not silently substituted", "Open the MRI of Priya Verma")
ask("Feature A: typo needs confirmation", "Open Prya Verma's OPG")
ask("Feature C: no context yet, so it asks", "Summarize her report")
ask("Feature B: dictation to structured draft", "Lower right third molar is horizontally impacted.")
ask("Feature B: uncertainty + negation labelled; unknown tooth number is not guessed",
    "Possible caries on tooth 36. No swelling. Lower left molar has a visible cavity.")
step("Speech-to-text endpoint (mock provider; swap STT_PROVIDER=api for Whisper)", "POST", "/transcribe",
     files={"file": ("dictation.txt", b"Open Priya Verma's latest CBCT report", "text/plain")})

# Unsupported-claim guard: simulate a hallucinating LLM and show the validator catching it.
bad_llm = lambda s, u: {"findings": [
    {"observation": "horizontal impaction", "site_text": "lower right third molar", "fdi_tooth": "48",
     "certainty": "stated", "source_phrase": "Lower right third molar is horizontally impacted"},
    {"observation": "periapical abscess", "site_text": "lower right third molar", "fdi_tooth": "48",
     "certainty": "stated", "source_phrase": "with an associated periapical abscess"}]}
draft = create_clinical_draft("Lower right third molar is horizontally impacted.", llm_call=bad_llm)
out.extend(["## Unsupported-claim guard (simulated hallucinating LLM)",
        "_The fake model adds a finding the clinician never said. The grounding validator discards it._", "",
        "```json", json.dumps({"extraction_method": draft["extraction_method"],
                               "findings": [f["observation"] for f in draft["findings"]],
                               "rejected_findings": draft["rejected_findings"], "warnings": draft["warnings"]},
                              indent=2), "```", ""])

(ROOT / "docs" / "DEMO_OUTPUT.md").write_text("\n".join(out), encoding="utf-8")
print(f"wrote docs/DEMO_OUTPUT.md ({n} calls)")
